/**
 * Database schema (Drizzle ORM / PostgreSQL).
 *
 * Conventions:
 *  - All PKs are UUID v4 generated by the database (gen_random_uuid()).
 *  - All timestamps are TIMESTAMPTZ stored in UTC.
 *  - Money is numeric(18,4) handled as *strings* in JS; use lib/money.ts (decimal.js)
 *    for any arithmetic. Every money amount has an explicit ISO currency code column.
 *  - Soft delete: `deleted_at` / `archived_at` where retention requires keeping records.
 *  - Personal data (applications, personnel) is kept in separate tables from auth users.
 */
import {
  pgTable, uuid, text, varchar, boolean, integer, numeric, timestamp, date,
  jsonb, pgEnum, index, uniqueIndex, check, bigserial, customType,
} from 'drizzle-orm/pg-core';
import { sql } from 'drizzle-orm';

/** numeric(18,4) exposed as string to avoid float precision loss. */
export const money = customType<{ data: string; driverData: string }>({
  dataType() { return 'numeric(18,4)'; },
  fromDriver(value) { return String(value); },
  toDriver(value) { return String(value); },
});

export const localeEnum = pgEnum('locale', ['ar', 'en']);
export const currencyEnum = pgEnum('currency', ['LBP', 'USD']);

// ---------------------------------------------------------------- users/auth

export const userRoleEnum = pgEnum('user_role', [
  'owner', 'admin', 'hr', 'pm', 'accountant', 'engineer', 'worker', 'customer',
]);
export const userStatusEnum = pgEnum('user_status', ['active', 'suspended', 'pending']);

export const users = pgTable('users', {
  id: uuid('id').primaryKey().defaultRandom(),
  email: varchar('email', { length: 320 }).notNull(),
  passwordHash: varchar('password_hash', { length: 200 }).notNull(),
  fullName: varchar('full_name', { length: 200 }).notNull(),
  role: userRoleEnum('role').notNull(),
  status: userStatusEnum('status').notNull().default('active'),
  locale: localeEnum('locale').notNull().default('en'),
  mfaEnabled: boolean('mfa_enabled').notNull().default(false),
  mfaSecret: varchar('mfa_secret', { length: 64 }),
  mustChangePassword: boolean('must_change_password').notNull().default(false),
  lastLoginAt: timestamp('last_login_at', { withTimezone: true }),
  failedLoginCount: integer('failed_login_count').notNull().default(0),
  lockedUntil: timestamp('locked_until', { withTimezone: true }),
  personnelId: uuid('personnel_id'), // link for engineer/worker accounts (set after personnel exists)
  customerId: uuid('customer_id'),    // link for customer accounts
  createdBy: uuid('created_by'),
  createdAt: timestamp('created_at', { withTimezone: true }).notNull().defaultNow(),
  updatedAt: timestamp('updated_at', { withTimezone: true }).notNull().defaultNow(),
  deletedAt: timestamp('deleted_at', { withTimezone: true }),
}, (t) => [
  uniqueIndex('users_email_unique_active').on(t.email).where(sql`deleted_at IS NULL`),
]);

export const sessions = pgTable('sessions', {
  id: uuid('id').primaryKey().defaultRandom(),
  tokenHash: varchar('token_hash', { length: 64 }).notNull(),
  userId: uuid('user_id').notNull().references(() => users.id, { onDelete: 'cascade' }),
  csrfToken: varchar('csrf_token', { length: 64 }).notNull(),
  mfaVerified: boolean('mfa_verified').notNull().default(false),
  expiresAt: timestamp('expires_at', { withTimezone: true }).notNull(),
  createdAt: timestamp('created_at', { withTimezone: true }).notNull().defaultNow(),
  lastSeenAt: timestamp('last_seen_at', { withTimezone: true }).notNull().defaultNow(),
  ip: varchar('ip', { length: 64 }),
  userAgent: varchar('user_agent', { length: 300 }),
}, (t) => [uniqueIndex('sessions_token_hash_idx').on(t.tokenHash), index('sessions_user_idx').on(t.userId)]);

export const passwordResets = pgTable('password_resets', {
  id: uuid('id').primaryKey().defaultRandom(),
  userId: uuid('user_id').notNull().references(() => users.id, { onDelete: 'cascade' }),
  tokenHash: varchar('token_hash', { length: 64 }).notNull(),
  expiresAt: timestamp('expires_at', { withTimezone: true }).notNull(),
  usedAt: timestamp('used_at', { withTimezone: true }),
  createdAt: timestamp('created_at', { withTimezone: true }).notNull().defaultNow(),
}, (t) => [uniqueIndex('password_resets_token_idx').on(t.tokenHash)]);

// ---------------------------------------------------------------- taxonomy

/** Configurable categories: trades, engineering disciplines AND customer request categories. */
export const categoryKindEnum = pgEnum('category_kind', ['trade', 'engineering', 'request', 'other']);

export const categories = pgTable('categories', {
  id: uuid('id').primaryKey().defaultRandom(),
  kind: categoryKindEnum('kind').notNull(),
  code: varchar('code', { length: 60 }).notNull(),
  nameEn: varchar('name_en', { length: 200 }).notNull(),
  nameAr: varchar('name_ar', { length: 200 }).notNull(),
  descriptionEn: text('description_en'),
  descriptionAr: text('description_ar'),
  active: boolean('active').notNull().default(true),
  sortOrder: integer('sort_order').notNull().default(0),
  createdAt: timestamp('created_at', { withTimezone: true }).notNull().defaultNow(),
}, (t) => [uniqueIndex('categories_kind_code_idx').on(t.kind, t.code)]);

/** Configurable public services shown on the website. */
export const services = pgTable('services', {
  id: uuid('id').primaryKey().defaultRandom(),
  slug: varchar('slug', { length: 120 }).notNull(),
  titleEn: varchar('title_en', { length: 200 }).notNull(),
  titleAr: varchar('title_ar', { length: 200 }).notNull(),
  summaryEn: text('summary_en'),
  summaryAr: text('summary_ar'),
  bodyEn: text('body_en'),
  bodyAr: text('body_ar'),
  iconKey: varchar('icon_key', { length: 60 }).notNull().default('tools'),
  published: boolean('published').notNull().default(true),
  sortOrder: integer('sort_order').notNull().default(0),
  createdAt: timestamp('created_at', { withTimezone: true }).notNull().defaultNow(),
  updatedAt: timestamp('updated_at', { withTimezone: true }).notNull().defaultNow(),
}, (t) => [uniqueIndex('services_slug_idx').on(t.slug)]);

/** Portfolio projects shown publicly (separate from internal projects; may reference one). */
export const portfolioProjects = pgTable('portfolio_projects', {
  id: uuid('id').primaryKey().defaultRandom(),
  projectId: uuid('project_id'),
  titleEn: varchar('title_en', { length: 200 }).notNull(),
  titleAr: varchar('title_ar', { length: 200 }).notNull(),
  descriptionEn: text('description_en'),
  descriptionAr: text('description_ar'),
  category: varchar('category', { length: 120 }),
  location: varchar('location', { length: 200 }),
  completedYear: integer('completed_year'),
  coverFileId: uuid('cover_file_id'),
  published: boolean('published').notNull().default(false),
  sortOrder: integer('sort_order').notNull().default(0),
  createdAt: timestamp('created_at', { withTimezone: true }).notNull().defaultNow(),
  updatedAt: timestamp('updated_at', { withTimezone: true }).notNull().defaultNow(),
});

// ---------------------------------------------------------------- files

export const files = pgTable('files', {
  id: uuid('id').primaryKey().defaultRandom(),
  storedName: varchar('stored_name', { length: 120 }).notNull(), // random name on disk
  originalName: varchar('original_name', { length: 300 }).notNull(),
  mimeType: varchar('mime_type', { length: 160 }).notNull(),
  sizeBytes: integer('size_bytes').notNull(),
  sha256: varchar('sha256', { length: 64 }).notNull(),
  /** polymorphic owner: application | personnel | request | project | quotation | contract | portfolio | other */
  ownerType: varchar('owner_type', { length: 40 }).notNull().default('other'),
  ownerId: uuid('owner_id'),
  visibility: varchar('visibility', { length: 20 }).notNull().default('private'), // private | public
  uploadedBy: uuid('uploaded_by'),
  createdAt: timestamp('created_at', { withTimezone: true }).notNull().defaultNow(),
  deletedAt: timestamp('deleted_at', { withTimezone: true }),
}, (t) => [uniqueIndex('files_stored_name_idx').on(t.storedName), index('files_owner_idx').on(t.ownerType, t.ownerId)]);

// ---------------------------------------------------------------- personnel

export const personTypeEnum = pgEnum('person_type', ['worker', 'technician', 'engineer', 'other']);
export const employmentStatusEnum = pgEnum('employment_status', [
  'candidate', 'active', 'on_leave', 'suspended', 'terminated', 'retired',
]);
export const availabilityEnum = pgEnum('availability', ['available', 'busy', 'unavailable']);
export const payModelEnum = pgEnum('pay_model', ['hourly', 'day_rate', 'fixed_work', 'monthly', 'unspecified']);

export const personnel = pgTable('personnel', {
  id: uuid('id').primaryKey().defaultRandom(),
  recordNo: varchar('record_no', { length: 30 }).notNull(), // e.g. EMP-000123
  personType: personTypeEnum('person_type').notNull().default('worker'),
  fullName: varchar('full_name', { length: 200 }).notNull(), // never auto-translated
  photoFileId: uuid('photo_file_id'),
  phone: varchar('phone', { length: 30 }).notNull(),
  altPhone: varchar('alt_phone', { length: 30 }),
  email: varchar('email', { length: 320 }),
  governorate: varchar('governorate', { length: 80 }),
  district: varchar('district', { length: 80 }),
  town: varchar('town', { length: 120 }),
  address: varchar('address', { length: 300 }),
  categoryId: uuid('category_id').references(() => categories.id),
  secondarySkills: text('secondary_skills'),
  experienceYears: integer('experience_years').notNull().default(0),
  qualifications: text('qualifications'),
  languages: varchar('languages', { length: 200 }),
  employmentStatus: employmentStatusEnum('employment_status').notNull().default('candidate'),
  availability: availabilityEnum('availability').notNull().default('available'),
  payModel: payModelEnum('pay_model').notNull().default('unspecified'),
  /** restricted to authorized roles (owner/admin/hr/accountant); never public */
  rateAmount: money('rate_amount'),
  rateCurrency: currencyEnum('rate_currency'),
  hireDate: date('hire_date'),
  emergencyContactName: varchar('emergency_contact_name', { length: 200 }), // restricted
  emergencyContactPhone: varchar('emergency_contact_phone', { length: 30 }), // restricted
  notes: text('notes'),
  archivedAt: timestamp('archived_at', { withTimezone: true }),
  mergedIntoId: uuid('merged_into_id'), // duplicate-merge support
  sourceApplicationId: uuid('source_application_id'),
  createdBy: uuid('created_by'),
  updatedBy: uuid('updated_by'),
  createdAt: timestamp('created_at', { withTimezone: true }).notNull().defaultNow(),
  updatedAt: timestamp('updated_at', { withTimezone: true }).notNull().defaultNow(),
  deletedAt: timestamp('deleted_at', { withTimezone: true }),
}, (t) => [
  uniqueIndex('personnel_record_no_idx').on(t.recordNo),
  index('personnel_search_idx').on(t.personType, t.employmentStatus),
  index('personnel_category_idx').on(t.categoryId),
  index('personnel_name_idx').on(t.fullName),
  index('personnel_phone_idx').on(t.phone),
  check('personnel_experience_range', sql`experience_years >= 0 AND experience_years <= 70`),
]);

/** Change history for important personnel fields. */
export const personnelHistory = pgTable('personnel_history', {
  id: bigserial('id', { mode: 'number' }).primaryKey(),
  personnelId: uuid('personnel_id').notNull().references(() => personnel.id, { onDelete: 'cascade' }),
  actorId: uuid('actor_id'),
  action: varchar('action', { length: 40 }).notNull(), // create|update|archive|restore|merge|status_change
  field: varchar('field', { length: 60 }),
  oldValue: text('old_value'),
  newValue: text('new_value'),
  createdAt: timestamp('created_at', { withTimezone: true }).notNull().defaultNow(),
}, (t) => [index('personnel_history_idx').on(t.personnelId)]);

// ---------------------------------------------------------------- job applications (public)

export const applicationStatusEnum = pgEnum('application_status', [
  'draft', 'submitted', 'under_review', 'shortlisted', 'interview', 'approved', 'rejected', 'hired',
]);

export const applications = pgTable('applications', {
  id: uuid('id').primaryKey().defaultRandom(),
  reference: varchar('reference', { length: 30 }).notNull(), // e.g. APP-2026-000001
  accessTokenHash: varchar('access_token_hash', { length: 64 }).notNull(), // sha256 of tracking token
  fullName: varchar('full_name', { length: 200 }).notNull(),
  phone: varchar('phone', { length: 30 }).notNull(),
  email: varchar('email', { length: 320 }),
  personType: personTypeEnum('person_type').notNull(),
  categoryId: uuid('category_id').references(() => categories.id),
  skills: text('skills'),
  experienceYears: integer('experience_years').notNull().default(0),
  qualifications: text('qualifications'),
  languages: varchar('languages', { length: 200 }),
  governorate: varchar('governorate', { length: 80 }),
  district: varchar('district', { length: 80 }),
  town: varchar('town', { length: 120 }),
  preferredLocations: text('preferred_locations'),
  availability: varchar('availability', { length: 60 }),
  expectedRate: money('expected_rate'),
  expectedRateCurrency: currencyEnum('expected_rate_currency'),
  consentGiven: boolean('consent_given').notNull().default(false),
  status: applicationStatusEnum('status').notNull().default('submitted'),
  /** internal: never exposed to the applicant */
  internalNotes: text('internal_notes'),
  evaluationScore: integer('evaluation_score'),
  /** applicant-visible message */
  publicMessage: text('public_message'),
  reviewedBy: uuid('reviewed_by'),
  reviewedAt: timestamp('reviewed_at', { withTimezone: true }),
  personnelId: uuid('personnel_id'), // set when converted to personnel record
  submittedAt: timestamp('submitted_at', { withTimezone: true }).notNull().defaultNow(),
  createdAt: timestamp('created_at', { withTimezone: true }).notNull().defaultNow(),
  updatedAt: timestamp('updated_at', { withTimezone: true }).notNull().defaultNow(),
}, (t) => [
  uniqueIndex('applications_reference_idx').on(t.reference),
  index('applications_status_idx').on(t.status),
  index('applications_category_idx').on(t.categoryId),
  index('applications_phone_idx').on(t.phone),
]);

export const applicationEvents = pgTable('application_events', {
  id: bigserial('id', { mode: 'number' }).primaryKey(),
  applicationId: uuid('application_id').notNull().references(() => applications.id, { onDelete: 'cascade' }),
  actorId: uuid('actor_id'), // null = applicant/system
  eventType: varchar('event_type', { length: 40 }).notNull(), // status_change|note|info_request|message
  fromStatus: varchar('from_status', { length: 30 }),
  toStatus: varchar('to_status', { length: 30 }),
  visibility: varchar('visibility', { length: 20 }).notNull().default('internal'), // internal|applicant
  messageAr: text('message_ar'),
  messageEn: text('message_en'),
  createdAt: timestamp('created_at', { withTimezone: true }).notNull().defaultNow(),
}, (t) => [index('application_events_idx').on(t.applicationId)]);

// ---------------------------------------------------------------- customers & requests

export const customers = pgTable('customers', {
  id: uuid('id').primaryKey().defaultRandom(),
  name: varchar('name', { length: 200 }).notNull(),
  company: varchar('company', { length: 200 }),
  phone: varchar('phone', { length: 30 }),
  altPhone: varchar('alt_phone', { length: 30 }),
  email: varchar('email', { length: 320 }),
  language: localeEnum('language').notNull().default('ar'),
  address: varchar('address', { length: 300 }),
  taxId: varchar('tax_id', { length: 60 }), // only with verified business need
  notes: text('notes'),
  createdAt: timestamp('created_at', { withTimezone: true }).notNull().defaultNow(),
  updatedAt: timestamp('updated_at', { withTimezone: true }).notNull().defaultNow(),
  deletedAt: timestamp('deleted_at', { withTimezone: true }),
}, (t) => [index('customers_name_idx').on(t.name), index('customers_phone_idx').on(t.phone)]);

export const requestStatusEnum = pgEnum('request_status', [
  'submitted', 'under_review', 'needs_info', 'site_visit', 'estimating',
  'quotation_prepared', 'quotation_sent', 'accepted', 'declined', 'expired',
  'contracted', 'in_progress', 'completed', 'cancelled',
]);

export const requests = pgTable('requests', {
  id: uuid('id').primaryKey().defaultRandom(),
  reference: varchar('reference', { length: 30 }).notNull(), // REQ-2026-000001
  accessTokenHash: varchar('access_token_hash', { length: 64 }).notNull(),
  customerId: uuid('customer_id').references(() => customers.id),
  contactName: varchar('contact_name', { length: 200 }).notNull(),
  phone: varchar('phone', { length: 30 }).notNull(),
  email: varchar('email', { length: 320 }),
  company: varchar('company', { length: 200 }),
  language: localeEnum('language').notNull().default('ar'),
  categoryId: uuid('category_id').references(() => categories.id), // request category
  description: text('description').notNull(),
  governorate: varchar('governorate', { length: 80 }),
  district: varchar('district', { length: 80 }),
  town: varchar('town', { length: 120 }),
  propertyType: varchar('property_type', { length: 60 }), // apartment|villa|building|commercial|land|other
  areaValue: numeric('area_value', { precision: 12, scale: 2 }),
  areaUnit: varchar('area_unit', { length: 10 }).notNull().default('m2'), // m2 | m
  desiredStart: date('desired_start'),
  deadline: date('deadline'),
  budget: money('budget'),
  budgetCurrency: currencyEnum('budget_currency'),
  preferredContact: varchar('preferred_contact', { length: 20 }).notNull().default('phone'), // phone|email|whatsapp
  consentGiven: boolean('consent_given').notNull().default(false),
  status: requestStatusEnum('status').notNull().default('submitted'),
  internalNotes: text('internal_notes'),
  assignedTo: uuid('assigned_to'),
  projectId: uuid('project_id'), // set after conversion
  submittedAt: timestamp('submitted_at', { withTimezone: true }).notNull().defaultNow(),
  createdAt: timestamp('created_at', { withTimezone: true }).notNull().defaultNow(),
  updatedAt: timestamp('updated_at', { withTimezone: true }).notNull().defaultNow(),
}, (t) => [
  uniqueIndex('requests_reference_idx').on(t.reference),
  index('requests_status_idx').on(t.status),
  index('requests_customer_idx').on(t.customerId),
]);

export const requestEvents = pgTable('request_events', {
  id: bigserial('id', { mode: 'number' }).primaryKey(),
  requestId: uuid('request_id').notNull().references(() => requests.id, { onDelete: 'cascade' }),
  actorId: uuid('actor_id'),
  eventType: varchar('event_type', { length: 40 }).notNull(), // status_change|note|message|site_visit|call
  fromStatus: varchar('from_status', { length: 30 }),
  toStatus: varchar('to_status', { length: 30 }),
  visibility: varchar('visibility', { length: 20 }).notNull().default('internal'),
  messageAr: text('message_ar'),
  messageEn: text('message_en'),
  createdAt: timestamp('created_at', { withTimezone: true }).notNull().defaultNow(),
}, (t) => [index('request_events_idx').on(t.requestId)]);

export const siteVisits = pgTable('site_visits', {
  id: uuid('id').primaryKey().defaultRandom(),
  requestId: uuid('request_id').references(() => requests.id, { onDelete: 'cascade' }),
  projectId: uuid('project_id'),
  scheduledAt: timestamp('scheduled_at', { withTimezone: true }).notNull(),
  visitorUserId: uuid('visitor_user_id'),
  location: varchar('location', { length: 300 }),
  status: varchar('status', { length: 20 }).notNull().default('scheduled'), // scheduled|done|cancelled
  notes: text('notes'),
  createdAt: timestamp('created_at', { withTimezone: true }).notNull().defaultNow(),
}, (t) => [index('site_visits_request_idx').on(t.requestId), index('site_visits_project_idx').on(t.projectId)]);

// ---------------------------------------------------------------- projects

export const projectStatusEnum = pgEnum('project_status', [
  'planning', 'in_progress', 'on_hold', 'completed', 'cancelled',
]);
export const priorityEnum = pgEnum('priority', ['low', 'normal', 'high', 'urgent']);

export const projects = pgTable('projects', {
  id: uuid('id').primaryKey().defaultRandom(),
  projectNo: varchar('project_no', { length: 30 }).notNull(), // PRJ-2026-0001
  name: varchar('name', { length: 200 }).notNull(),
  customerId: uuid('customer_id').references(() => customers.id),
  requestId: uuid('request_id'),
  description: text('description'),
  scope: text('scope'),
  governorate: varchar('governorate', { length: 80 }),
  district: varchar('district', { length: 80 }),
  town: varchar('town', { length: 120 }),
  address: varchar('address', { length: 300 }),
  status: projectStatusEnum('status').notNull().default('planning'),
  priority: priorityEnum('priority').notNull().default('normal'),
  managerId: uuid('manager_id').references(() => users.id),
  startDate: date('start_date'),
  targetEndDate: date('target_end_date'),
  actualEndDate: date('actual_end_date'),
  contractAmount: money('contract_amount'),
  contractCurrency: currencyEnum('contract_currency'),
  budgetAmount: money('budget_amount'),
  budgetCurrency: currencyEnum('budget_currency'),
  warrantyNotes: text('warranty_notes'),
  archivedAt: timestamp('archived_at', { withTimezone: true }),
  createdBy: uuid('created_by'),
  createdAt: timestamp('created_at', { withTimezone: true }).notNull().defaultNow(),
  updatedAt: timestamp('updated_at', { withTimezone: true }).notNull().defaultNow(),
}, (t) => [
  uniqueIndex('projects_no_idx').on(t.projectNo),
  index('projects_status_idx').on(t.status),
  index('projects_manager_idx').on(t.managerId),
  index('projects_customer_idx').on(t.customerId),
]);

export const milestones = pgTable('milestones', {
  id: uuid('id').primaryKey().defaultRandom(),
  projectId: uuid('project_id').notNull().references(() => projects.id, { onDelete: 'cascade' }),
  title: varchar('title', { length: 200 }).notNull(),
  description: text('description'),
  dueDate: date('due_date'),
  completedAt: timestamp('completed_at', { withTimezone: true }),
  status: varchar('status', { length: 20 }).notNull().default('pending'), // pending|in_progress|done
  weight: integer('weight').notNull().default(1), // relative weight for progress calc
  sortOrder: integer('sort_order').notNull().default(0),
  createdAt: timestamp('created_at', { withTimezone: true }).notNull().defaultNow(),
}, (t) => [index('milestones_project_idx').on(t.projectId)]);

export const taskStatusEnum = pgEnum('task_status', ['todo', 'in_progress', 'blocked', 'done']);

export const tasks = pgTable('tasks', {
  id: uuid('id').primaryKey().defaultRandom(),
  projectId: uuid('project_id').notNull().references(() => projects.id, { onDelete: 'cascade' }),
  milestoneId: uuid('milestone_id').references(() => milestones.id, { onDelete: 'set null' }),
  title: varchar('title', { length: 200 }).notNull(),
  description: text('description'),
  status: taskStatusEnum('status').notNull().default('todo'),
  priority: priorityEnum('priority').notNull().default('normal'),
  assigneePersonnelId: uuid('assignee_personnel_id').references(() => personnel.id, { onDelete: 'set null' }),
  assigneeUserId: uuid('assignee_user_id').references(() => users.id, { onDelete: 'set null' }),
  dueDate: date('due_date'),
  completedAt: timestamp('completed_at', { withTimezone: true }),
  sortOrder: integer('sort_order').notNull().default(0),
  createdAt: timestamp('created_at', { withTimezone: true }).notNull().defaultNow(),
  updatedAt: timestamp('updated_at', { withTimezone: true }).notNull().defaultNow(),
}, (t) => [index('tasks_project_idx').on(t.projectId), index('tasks_assignee_idx').on(t.assigneePersonnelId)]);

export const projectTeam = pgTable('project_team', {
  id: uuid('id').primaryKey().defaultRandom(),
  projectId: uuid('project_id').notNull().references(() => projects.id, { onDelete: 'cascade' }),
  personnelId: uuid('personnel_id').references(() => personnel.id, { onDelete: 'cascade' }),
  userId: uuid('user_id').references(() => users.id, { onDelete: 'cascade' }),
  roleInProject: varchar('role_in_project', { length: 80 }),
  assignedAt: timestamp('assigned_at', { withTimezone: true }).notNull().defaultNow(),
  assignedBy: uuid('assigned_by'),
  removedAt: timestamp('removed_at', { withTimezone: true }),
}, (t) => [
  uniqueIndex('project_team_unique_personnel').on(t.projectId, t.personnelId),
  uniqueIndex('project_team_unique_user').on(t.projectId, t.userId),
]);

export const issueSeverityEnum = pgEnum('issue_severity', ['low', 'medium', 'high', 'critical']);

export const issues = pgTable('issues', {
  id: uuid('id').primaryKey().defaultRandom(),
  projectId: uuid('project_id').notNull().references(() => projects.id, { onDelete: 'cascade' }),
  title: varchar('title', { length: 200 }).notNull(),
  description: text('description'),
  kind: varchar('kind', { length: 20 }).notNull().default('issue'), // issue|risk
  severity: issueSeverityEnum('severity').notNull().default('medium'),
  status: varchar('status', { length: 20 }).notNull().default('open'), // open|mitigating|closed
  ownerId: uuid('owner_id'),
  createdAt: timestamp('created_at', { withTimezone: true }).notNull().defaultNow(),
  updatedAt: timestamp('updated_at', { withTimezone: true }).notNull().defaultNow(),
}, (t) => [index('issues_project_idx').on(t.projectId)]);

export const projectNotes = pgTable('project_notes', {
  id: uuid('id').primaryKey().defaultRandom(),
  projectId: uuid('project_id').notNull().references(() => projects.id, { onDelete: 'cascade' }),
  authorId: uuid('author_id'),
  body: text('body').notNull(),
  createdAt: timestamp('created_at', { withTimezone: true }).notNull().defaultNow(),
}, (t) => [index('project_notes_idx').on(t.projectId)]);

export const completionChecklist = pgTable('completion_checklist', {
  id: uuid('id').primaryKey().defaultRandom(),
  projectId: uuid('project_id').notNull().references(() => projects.id, { onDelete: 'cascade' }),
  item: varchar('item', { length: 300 }).notNull(),
  done: boolean('done').notNull().default(false),
  doneBy: uuid('done_by'),
  doneAt: timestamp('done_at', { withTimezone: true }),
  sortOrder: integer('sort_order').notNull().default(0),
});

// ---------------------------------------------------------------- scheduling / attendance / payments

export const shiftEnum = pgEnum('shift', ['morning', 'afternoon', 'full_day', 'night']);

/** Daily assignment of a person to a project. UNIQUE(personnel, date) prevents double-booking. */
export const assignments = pgTable('assignments', {
  id: uuid('id').primaryKey().defaultRandom(),
  personnelId: uuid('personnel_id').notNull().references(() => personnel.id, { onDelete: 'cascade' }),
  projectId: uuid('project_id').notNull().references(() => projects.id, { onDelete: 'cascade' }),
  workDate: date('work_date').notNull(),
  shift: shiftEnum('shift').notNull().default('full_day'),
  notes: varchar('notes', { length: 300 }),
  createdBy: uuid('created_by'),
  createdAt: timestamp('created_at', { withTimezone: true }).notNull().defaultNow(),
}, (t) => [
  uniqueIndex('assignments_unique_person_day').on(t.personnelId, t.workDate),
  index('assignments_project_date_idx').on(t.projectId, t.workDate),
]);

export const attendanceStatusEnum = pgEnum('attendance_status', ['present', 'absent', 'late', 'leave', 'half_day']);
export const approvalStatusEnum = pgEnum('approval_status', ['draft', 'submitted', 'approved', 'rejected']);

export const attendance = pgTable('attendance', {
  id: uuid('id').primaryKey().defaultRandom(),
  personnelId: uuid('personnel_id').notNull().references(() => personnel.id, { onDelete: 'cascade' }),
  projectId: uuid('project_id').references(() => projects.id, { onDelete: 'set null' }),
  workDate: date('work_date').notNull(),
  status: attendanceStatusEnum('status').notNull().default('present'),
  regularHours: numeric('regular_hours', { precision: 5, scale: 2 }).notNull().default('0'),
  overtimeHours: numeric('overtime_hours', { precision: 5, scale: 2 }).notNull().default('0'),
  notes: varchar('notes', { length: 300 }),
  approvalStatus: approvalStatusEnum('approval_status').notNull().default('draft'),
  submittedBy: uuid('submitted_by'),
  submittedAt: timestamp('submitted_at', { withTimezone: true }),
  approvedBy: uuid('approved_by'),
  approvedAt: timestamp('approved_at', { withTimezone: true }),
  createdAt: timestamp('created_at', { withTimezone: true }).notNull().defaultNow(),
  updatedAt: timestamp('updated_at', { withTimezone: true }).notNull().defaultNow(),
}, (t) => [
  uniqueIndex('attendance_unique_person_day').on(t.personnelId, t.workDate),
  index('attendance_project_idx').on(t.projectId, t.workDate),
]);

export const workerPaymentTypeEnum = pgEnum('worker_payment_type', ['advance', 'payment', 'settlement']);

export const workerPayments = pgTable('worker_payments', {
  id: uuid('id').primaryKey().defaultRandom(),
  personnelId: uuid('personnel_id').notNull().references(() => personnel.id, { onDelete: 'cascade' }),
  projectId: uuid('project_id').references(() => projects.id, { onDelete: 'set null' }),
  type: workerPaymentTypeEnum('type').notNull().default('payment'),
  amount: money('amount').notNull(),
  currency: currencyEnum('currency').notNull(),
  paidOn: date('paid_on').notNull(),
  method: varchar('method', { length: 30 }).notNull().default('cash'), // cash|transfer|check
  reference: varchar('reference', { length: 80 }),
  notes: varchar('notes', { length: 300 }),
  status: approvalStatusEnum('status').notNull().default('draft'),
  approvedBy: uuid('approved_by'),
  createdBy: uuid('created_by'),
  createdAt: timestamp('created_at', { withTimezone: true }).notNull().defaultNow(),
}, (t) => [index('worker_payments_personnel_idx').on(t.personnelId), index('worker_payments_project_idx').on(t.projectId)]);

// ---------------------------------------------------------------- finance

export const suppliers = pgTable('suppliers', {
  id: uuid('id').primaryKey().defaultRandom(),
  name: varchar('name', { length: 200 }).notNull(),
  kind: varchar('kind', { length: 30 }).notNull().default('supplier'), // supplier|subcontractor
  phone: varchar('phone', { length: 30 }),
  email: varchar('email', { length: 320 }),
  address: varchar('address', { length: 300 }),
  notes: text('notes'),
  createdAt: timestamp('created_at', { withTimezone: true }).notNull().defaultNow(),
  deletedAt: timestamp('deleted_at', { withTimezone: true }),
});

export const quotationStatusEnum = pgEnum('quotation_status', [
  'draft', 'pending_approval', 'approved', 'sent', 'accepted', 'declined', 'expired', 'cancelled',
]);

export const quotations = pgTable('quotations', {
  id: uuid('id').primaryKey().defaultRandom(),
  quoteNo: varchar('quote_no', { length: 30 }).notNull(),
  version: integer('version').notNull().default(1),
  supersedesId: uuid('supersedes_id'),
  customerId: uuid('customer_id').notNull().references(() => customers.id),
  requestId: uuid('request_id'),
  projectId: uuid('project_id'),
  status: quotationStatusEnum('status').notNull().default('draft'),
  currency: currencyEnum('currency').notNull(),
  title: varchar('title', { length: 200 }),
  scopeOfWork: text('scope_of_work'),
  assumptions: text('assumptions'),
  exclusions: text('exclusions'),
  paymentTerms: text('payment_terms'),
  validUntil: date('valid_until'),
  discountPct: numeric('discount_pct', { precision: 5, scale: 2 }).notNull().default('0'),
  taxPct: numeric('tax_pct', { precision: 5, scale: 2 }).notNull().default('0'),
  subtotal: money('subtotal').notNull().default('0'),
  discountAmount: money('discount_amount').notNull().default('0'),
  taxAmount: money('tax_amount').notNull().default('0'),
  total: money('total').notNull().default('0'),
  approvedBy: uuid('approved_by'),
  approvedAt: timestamp('approved_at', { withTimezone: true }),
  sentAt: timestamp('sent_at', { withTimezone: true }),
  respondedAt: timestamp('responded_at', { withTimezone: true }),
  createdBy: uuid('created_by'),
  createdAt: timestamp('created_at', { withTimezone: true }).notNull().defaultNow(),
  updatedAt: timestamp('updated_at', { withTimezone: true }).notNull().defaultNow(),
}, (t) => [
  uniqueIndex('quotations_no_version_idx').on(t.quoteNo, t.version),
  index('quotations_customer_idx').on(t.customerId),
  index('quotations_status_idx').on(t.status),
]);

export const quoteItemKindEnum = pgEnum('quote_item_kind', ['labor', 'material', 'equipment', 'other']);

export const quotationItems = pgTable('quotation_items', {
  id: uuid('id').primaryKey().defaultRandom(),
  quotationId: uuid('quotation_id').notNull().references(() => quotations.id, { onDelete: 'cascade' }),
  kind: quoteItemKindEnum('kind').notNull().default('other'),
  description: varchar('description', { length: 400 }).notNull(),
  qty: numeric('qty', { precision: 12, scale: 3 }).notNull().default('1'),
  unit: varchar('unit', { length: 30 }).notNull().default('unit'),
  unitPrice: money('unit_price').notNull(),
  lineTotal: money('line_total').notNull(),
  sortOrder: integer('sort_order').notNull().default(0),
}, (t) => [index('quotation_items_idx').on(t.quotationId)]);

export const contractStatusEnum = pgEnum('contract_status', ['draft', 'active', 'completed', 'terminated']);

export const contracts = pgTable('contracts', {
  id: uuid('id').primaryKey().defaultRandom(),
  contractNo: varchar('contract_no', { length: 30 }).notNull(),
  customerId: uuid('customer_id').notNull().references(() => customers.id),
  projectId: uuid('project_id').references(() => projects.id),
  quotationId: uuid('quotation_id'),
  status: contractStatusEnum('status').notNull().default('draft'),
  amount: money('amount').notNull(),
  currency: currencyEnum('currency').notNull(),
  startDate: date('start_date'),
  endDate: date('end_date'),
  scope: text('scope'),
  notes: text('notes'),
  documentFileId: uuid('document_file_id'),
  signedAt: timestamp('signed_at', { withTimezone: true }),
  createdBy: uuid('created_by'),
  createdAt: timestamp('created_at', { withTimezone: true }).notNull().defaultNow(),
  updatedAt: timestamp('updated_at', { withTimezone: true }).notNull().defaultNow(),
}, (t) => [uniqueIndex('contracts_no_idx').on(t.contractNo)]);

/** Planned payment schedule lines on a contract. */
export const contractPayments = pgTable('contract_payments', {
  id: uuid('id').primaryKey().defaultRandom(),
  contractId: uuid('contract_id').notNull().references(() => contracts.id, { onDelete: 'cascade' }),
  label: varchar('label', { length: 200 }).notNull(),
  dueDate: date('due_date'),
  amountPct: numeric('amount_pct', { precision: 5, scale: 2 }),
  amount: money('amount'),
  sortOrder: integer('sort_order').notNull().default(0),
});

export const changeOrders = pgTable('change_orders', {
  id: uuid('id').primaryKey().defaultRandom(),
  coNo: varchar('co_no', { length: 30 }).notNull(),
  contractId: uuid('contract_id').notNull().references(() => contracts.id, { onDelete: 'cascade' }),
  projectId: uuid('project_id'),
  title: varchar('title', { length: 200 }).notNull(),
  description: text('description'),
  amount: money('amount').notNull(),
  currency: currencyEnum('currency').notNull(),
  status: varchar('status', { length: 20 }).notNull().default('proposed'), // proposed|approved|rejected
  approvedBy: uuid('approved_by'),
  approvedAt: timestamp('approved_at', { withTimezone: true }),
  createdAt: timestamp('created_at', { withTimezone: true }).notNull().defaultNow(),
}, (t) => [uniqueIndex('change_orders_no_idx').on(t.coNo)]);

export const invoiceStatusEnum = pgEnum('invoice_status', ['draft', 'sent', 'partial', 'paid', 'cancelled']);

export const invoices = pgTable('invoices', {
  id: uuid('id').primaryKey().defaultRandom(),
  invoiceNo: varchar('invoice_no', { length: 30 }).notNull(),
  customerId: uuid('customer_id').notNull().references(() => customers.id),
  projectId: uuid('project_id'),
  contractId: uuid('contract_id'),
  quotationId: uuid('quotation_id'),
  status: invoiceStatusEnum('status').notNull().default('draft'),
  currency: currencyEnum('currency').notNull(),
  issueDate: date('issue_date').notNull(),
  dueDate: date('due_date'),
  subtotal: money('subtotal').notNull().default('0'),
  taxPct: numeric('tax_pct', { precision: 5, scale: 2 }).notNull().default('0'),
  taxAmount: money('tax_amount').notNull().default('0'),
  total: money('total').notNull().default('0'),
  paidTotal: money('paid_total').notNull().default('0'), // maintained in transactions
  notes: text('notes'),
  createdBy: uuid('created_by'),
  createdAt: timestamp('created_at', { withTimezone: true }).notNull().defaultNow(),
  updatedAt: timestamp('updated_at', { withTimezone: true }).notNull().defaultNow(),
}, (t) => [
  uniqueIndex('invoices_no_idx').on(t.invoiceNo),
  index('invoices_customer_idx').on(t.customerId),
  index('invoices_status_idx').on(t.status),
]);

export const invoiceItems = pgTable('invoice_items', {
  id: uuid('id').primaryKey().defaultRandom(),
  invoiceId: uuid('invoice_id').notNull().references(() => invoices.id, { onDelete: 'cascade' }),
  description: varchar('description', { length: 400 }).notNull(),
  qty: numeric('qty', { precision: 12, scale: 3 }).notNull().default('1'),
  unit: varchar('unit', { length: 30 }).notNull().default('unit'),
  unitPrice: money('unit_price').notNull(),
  lineTotal: money('line_total').notNull(),
  sortOrder: integer('sort_order').notNull().default(0),
}, (t) => [index('invoice_items_idx').on(t.invoiceId)]);

export const receipts = pgTable('receipts', {
  id: uuid('id').primaryKey().defaultRandom(),
  receiptNo: varchar('receipt_no', { length: 30 }).notNull(),
  invoiceId: uuid('invoice_id').references(() => invoices.id),
  customerId: uuid('customer_id').notNull().references(() => customers.id),
  projectId: uuid('project_id'),
  amount: money('amount').notNull(),
  currency: currencyEnum('currency').notNull(),
  method: varchar('method', { length: 30 }).notNull().default('cash'), // cash|transfer|check|card
  externalRef: varchar('external_ref', { length: 120 }), // bank/check reference
  receivedOn: date('received_on').notNull(),
  notes: varchar('notes', { length: 300 }),
  recordedBy: uuid('recorded_by'),
  createdAt: timestamp('created_at', { withTimezone: true }).notNull().defaultNow(),
  voidedAt: timestamp('voided_at', { withTimezone: true }),
}, (t) => [
  uniqueIndex('receipts_no_idx').on(t.receiptNo),
  // duplicate-payment guard: same invoice + same external reference cannot repeat
  uniqueIndex('receipts_dup_guard_idx').on(t.invoiceId, t.externalRef).where(sql`external_ref IS NOT NULL AND voided_at IS NULL`),
  index('receipts_invoice_idx').on(t.invoiceId),
]);

export const expenseCategoryEnum = pgEnum('expense_category', [
  'labor', 'materials', 'equipment', 'transportation', 'subcontractor', 'miscellaneous',
]);

export const expenses = pgTable('expenses', {
  id: uuid('id').primaryKey().defaultRandom(),
  projectId: uuid('project_id').notNull().references(() => projects.id, { onDelete: 'cascade' }),
  category: expenseCategoryEnum('category').notNull(),
  description: varchar('description', { length: 300 }).notNull(),
  amount: money('amount').notNull(),
  currency: currencyEnum('currency').notNull(),
  expenseDate: date('expense_date').notNull(),
  supplierId: uuid('supplier_id').references(() => suppliers.id),
  receiptFileId: uuid('receipt_file_id'),
  recordedBy: uuid('recorded_by'),
  createdAt: timestamp('created_at', { withTimezone: true }).notNull().defaultNow(),
  updatedAt: timestamp('updated_at', { withTimezone: true }).notNull().defaultNow(),
}, (t) => [index('expenses_project_idx').on(t.projectId, t.category)]);

/**
 * Exchange rates. Rates are entered/configured by an authorized user or a verified
 * provider; the platform NEVER invents rates. Each row stores rate + timestamp + source.
 */
export const exchangeRates = pgTable('exchange_rates', {
  id: uuid('id').primaryKey().defaultRandom(),
  fromCurrency: currencyEnum('from_currency').notNull(),
  toCurrency: currencyEnum('to_currency').notNull(),
  rate: numeric('rate', { precision: 18, scale: 8 }).notNull(),
  rateDate: date('rate_date').notNull(),
  source: varchar('source', { length: 120 }).notNull().default('manual'),
  enteredBy: uuid('entered_by'),
  createdAt: timestamp('created_at', { withTimezone: true }).notNull().defaultNow(),
}, (t) => [
  index('exchange_rates_idx').on(t.fromCurrency, t.toCurrency, t.rateDate),
  check('exchange_rate_positive', sql`rate > 0`),
  check('exchange_rate_diff_currency', sql`from_currency <> to_currency`),
]);

// ---------------------------------------------------------------- notifications / audit / settings

export const notificationChannelEnum = pgEnum('notification_channel', ['inapp', 'email']);
export const notificationStatusEnum = pgEnum('notification_status', ['pending', 'sent', 'failed', 'skipped']);

export const notifications = pgTable('notifications', {
  id: uuid('id').primaryKey().defaultRandom(),
  userId: uuid('user_id').references(() => users.id, { onDelete: 'cascade' }),
  channel: notificationChannelEnum('channel').notNull(),
  toEmail: varchar('to_email', { length: 320 }),
  locale: localeEnum('locale').notNull().default('en'),
  templateKey: varchar('template_key', { length: 80 }).notNull(),
  payload: jsonb('payload').notNull().default(sql`'{}'::jsonb`),
  subject: varchar('subject', { length: 300 }),
  body: text('body'),
  status: notificationStatusEnum('status').notNull().default('pending'),
  attempts: integer('attempts').notNull().default(0),
  lastError: varchar('last_error', { length: 300 }),
  dedupeKey: varchar('dedupe_key', { length: 160 }),
  readAt: timestamp('read_at', { withTimezone: true }),
  sentAt: timestamp('sent_at', { withTimezone: true }),
  createdAt: timestamp('created_at', { withTimezone: true }).notNull().defaultNow(),
}, (t) => [
  index('notifications_user_idx').on(t.userId, t.readAt),
  uniqueIndex('notifications_dedupe_idx').on(t.dedupeKey).where(sql`dedupe_key IS NOT NULL`),
]);

export const auditEvents = pgTable('audit_events', {
  id: bigserial('id', { mode: 'number' }).primaryKey(),
  actorId: uuid('actor_id'), // null = anonymous/system
  actorEmail: varchar('actor_email', { length: 320 }),
  action: varchar('action', { length: 80 }).notNull(), // e.g. auth.login_failed, personnel.update
  entityType: varchar('entity_type', { length: 40 }),
  entityId: varchar('entity_id', { length: 64 }),
  summary: jsonb('summary').notNull().default(sql`'{}'::jsonb`), // minimal, redacted
  ip: varchar('ip', { length: 64 }),
  requestId: varchar('request_id', { length: 64 }),
  createdAt: timestamp('created_at', { withTimezone: true }).notNull().defaultNow(),
}, (t) => [
  index('audit_events_entity_idx').on(t.entityType, t.entityId),
  index('audit_events_actor_idx').on(t.actorId),
  index('audit_events_created_idx').on(t.createdAt),
]);

/** Key/value application settings (company profile, branding, numbering, locale defaults...). */
export const settings = pgTable('settings', {
  key: varchar('key', { length: 120 }).primaryKey(),
  value: jsonb('value').notNull(),
  updatedBy: uuid('updated_by'),
  updatedAt: timestamp('updated_at', { withTimezone: true }).notNull().defaultNow(),
});

/** Counters for document numbering (locked with SELECT ... FOR UPDATE inside transactions). */
export const docCounters = pgTable('doc_counters', {
  key: varchar('key', { length: 120 }).primaryKey(), // e.g. PRJ-2026
  lastValue: integer('last_value').notNull().default(0),
});

export type User = typeof users.$inferSelect;
export type Personnel = typeof personnel.$inferSelect;
export type Application = typeof applications.$inferSelect;
export type Request = typeof requests.$inferSelect;
export type Project = typeof projects.$inferSelect;
export type Quotation = typeof quotations.$inferSelect;
export type Invoice = typeof invoices.$inferSelect;
